function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 500) return 's must have 1 to 500 characters.';
  if (!/^[A-Za-z]+( [A-Za-z]+)*$/.test(s)) return 's must be letter-only words separated by single spaces, with no space at either end.';
  const count = s.split(' ').length;
  if (!Number.isInteger(k) || k < 1 || k > count) return 'k must be between 1 and the number of words in s.';
  return null;
}

