function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const word = (maxLength) => {
    const length = 1 + Math.floor(rand() * maxLength);
    let text = '';
    for (let i = 0; i < length; i++) text += letters[Math.floor(rand() * letters.length)];
    return text;
  };
  const words = [];
  if (size === 'small') {
    const count = 1 + Math.floor(rand() * 6);
    for (let i = 0; i < count; i++) words.push(word(4));
  } else {
    const maxLength = rand() < 0.5 ? 1 : 12;
    let length = -1;
    for (;;) {
      const next = word(maxLength);
      if (length + 1 + next.length > 500) break;
      words.push(next);
      length += 1 + next.length;
    }
  }
  const k = 1 + Math.floor(rand() * words.length);
  return [words.join(' '), k];
}
